{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Canrenone, a steroidal 17-spirolactone closely related to the query scaffold, showed near-complete oral bioavailability in humans (F0-∞ ≈ 98%), directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Eplerenone, another steroidal 17-spirolactone mineralocorticoid antagonist, has an absolute oral bioavailability of about 98% in humans, providing strong structural and mechanistic support for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Hydrocortisone, a corticosteroid with high oral bioavailability (absolute F ≈ 93% in healthy volunteers), demonstrates that steroid oral bioavailability can be high despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Medroxyprogesterone acetate has low oral bioavailability (<15%) due to gut and liver metabolism; this is contradictory evidence but less transferable because it lacks the spirolactone and cyclopropane modifications of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Testosterone has very low absolute oral bioavailability (~3.7%) due to extensive first-pass metabolism; this is contradictory but weakly transferable because the query's spirolactone and cyclopropane groups are associated with much higher metabolic stability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a steroidal 17-spirolactone with cyclopropane substitutions. The closest structural analogues with the same spirolactone motif, canrenone and eplerenone, show near-complete oral bioavailability in humans, and other corticosteroids also show high F. Low-F progestins and androgens are less transferable because they lack the spirolactone scaffold and undergo extensive first-pass metabolism. Overall evidence strongly supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself was retrieved.",
    "Eplerenone bioavailability estimates vary (69% vs ~98%), and hydrocortisone estimates range from 54% to 96%, adding some quantitative uncertainty.",
    "Low-F progestin/androgen records show that steroid class alone is not sufficient, but their structural divergence limits their relevance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

